    def sort_patients(self, plan: CommandPlan, state: dict) -> CommandResult:
        from ..command_envelope import HomeSortEntities
        guard = self._available(plan.action)
        if guard is not None:
            return guard
        try:
            entities = HomeSortEntities.model_validate(plan.entities)
        except ValueError:
            return CommandResult(ok=False, action=plan.action, error_code='INVALID_SORT')
        if not self._home.sort_patients(entities.column, entities.order):
            return CommandResult(ok=False, action=plan.action, error_code='SORT_FAILED')
        return CommandResult(ok=True, action=plan.action,
            message='Patient list sorting applied.', data=entities.model_dump())

    def advanced_search_patients(self,plan,state):
        result=self.list_patients(plan,state)
        result.action=plan.action
        return result

    def search_patients(self, plan: CommandPlan, state: dict) -> CommandResult:
        if plan.entities.get('source', 'local') not in ('local', 'server'):
            return CommandResult(ok=False, action=plan.action, error_code='INVALID_SOURCE')
        query = plan.model_copy(update={'entities':{'source':'local', **plan.entities}})
        result = self.list_patients(query, state)
        if not result.ok:
            result.action = plan.action
            return result
        return self.read_patients(query, state)

    def read_patients(self, plan: CommandPlan, state: dict) -> CommandResult:
        guard = self._available(plan.action)
        if guard is not None: return guard
        limit = max(1, min(int(plan.entities.get('limit', 25)), 200))
        pending = getattr(getattr(self._home, 'home', None), '_search_task', None)
        if pending is not None and not pending.done():
            return CommandResult(ok=True, action=plan.action, data={'state':'searching', 'rows':[], 'count':0})
        if pending is not None:
            try:
                pending.result()
            except BaseException:
                return CommandResult(ok=False, action=plan.action, error_code="HOME_SEARCH_FAILED",
                                     message="The patient search did not complete successfully.")
        rows = list(self._home.list_rows() or [])
        from .home_selection_adapter import HomeSelectionAdapter, list_identity
        home = getattr(self._home, 'home', None)
        source = 'unknown'
        if home is not None and getattr(home, 'patient_table_widget', None) is not None:
            selection = HomeSelectionAdapter(home)
            rows = selection._rows()
            source = selection._source()
        receipt = list_identity(rows, source)
        # Client-owned bounded receipts retain only the identities actually offered.
        self._ordinal_receipts.pop(receipt, None)
        self._ordinal_receipts[receipt] = (source, tuple(
            (str((row or {}).get('patient_id') or ''), str((row or {}).get('study_uid') or ''))
            for row in rows[:limit]))
        while len(self._ordinal_receipts) > 16:
            self._ordinal_receipts.pop(next(iter(self._ordinal_receipts)))
        rows = [dict(row, row_index=index, list_id=receipt) for index, row in enumerate(rows, 1) if row]
        return CommandResult(ok=True, action=plan.action,
                             data={'state':'ready', 'rows': rows[:limit], 'count':len(rows),
                                   'truncated':len(rows)>limit, 'list_id':receipt})

    def list_patients(self, plan: CommandPlan, state: dict) -> CommandResult:
        guard = self._available("list_patients")
        if guard is not None:
            return guard
        ent = plan.entities or {}
        criteria: dict[str, Any] = {
            "patient_id":   str(ent.get("patient_id") or ""),
            "patient_name": str(ent.get("patient_name") or ""),
            "date_from":    str(ent.get("date_from") or ""),
            "date_to":      str(ent.get("date_to") or ""),
        }
        for field in ('body_part', 'age_min', 'age_max', 'patient_ids'):
            if field in ent:
                criteria[field] = ent[field]
        modality = ent.get("modality")
        if modality:
            criteria["modality"] = str(modality)
        source = str(ent.get("source") or "active_tab")
        try:
            start = getattr(self._home, "start_search", None)
            if callable(start):
                task = start(source=source, criteria=criteria)
                if task is not None and not task.done():
                    return CommandResult(ok=True, action="list_patients",
                        message="Search started; poll read_patients until state is ready.",
                        data={"state": "searching", "rows": [], "count": 0})
                if task is not None:
                    task.result()
            else:
                self._home.search(source=source, criteria=criteria)
        except Exception as exc:
            return CommandResult(
                ok=False, action="list_patients",
                message=f"search failed: {exc}",
                error_code="HOME_SEARCH_FAILED",
            )
        # Try to surface the post-search row count if the adapter exposes it.
        rows: list = []
        for attr in ("list_rows", "read_patient_rows", "get_patient_rows", "patient_rows"):
            getter = getattr(self._home, attr, None)
            if callable(getter):
                try:
                    rows = list(getter() or [])
                    break
                except Exception:
                    rows = []
        return CommandResult(
            ok=True,
            action="list_patients",
            message=f"Listed {len(rows)} patients" if rows else "Search submitted",
            data={"state": "ready", "rows": rows, "count": len(rows), "criteria": criteria},
        )

