    def open_patient(self, plan: CommandPlan, state: dict) -> CommandResult:
        guard = self._available("open_patient")
        if guard is not None:
            return guard
        ent = plan.entities or {}
        if ent.get('row_index') is not None:
            from .home_selection_adapter import HomeSelectionAdapter, list_identity
            home = getattr(self._home, 'home', None)
            pending = getattr(home, '_search_task', None)
            if pending is not None and not pending.done():
                return CommandResult(ok=False, action=plan.action, error_code='SEARCH_PENDING',
                                     message='The search is still loading. Wait for it to finish before opening a study.')
            selection = HomeSelectionAdapter(home)
            rows = selection._rows()
            index = ent['row_index']
            captured = self._ordinal_receipts.get(ent.get('list_id'))
            if captured is not None:
                source, identities = captured
                if source != selection._source():
                    return CommandResult(ok=False, action=plan.action, error_code='STALE_LIST',
                                         message='The patient source changed. Read the current list and confirm again.')
                if type(index) is not int or not 1 <= index <= len(identities):
                    return CommandResult(ok=False, action=plan.action, error_code='ROW_OUT_OF_RANGE')
                target = identities[index - 1]
                matches = [row for row in rows if row and
                           (str(row.get('patient_id') or ''), str(row.get('study_uid') or '')) == target]
                if not all(target) or len(matches) != 1:
                    return CommandResult(ok=False, action=plan.action, error_code='STALE_LIST',
                                         message='The original study is missing or ambiguous. Read the current list and confirm again.')
                row = matches[0]
            else:
                # Snapshot-free callers retain the strict current-order contract.
                if ent.get('list_id') != list_identity(rows, selection._source()):
                    return CommandResult(ok=False, action=plan.action, error_code='STALE_LIST',
                                         message='The patient list changed and its original receipt is unavailable. Read the list again.')
                if type(index) is not int or not 1 <= index <= len(rows):
                    return CommandResult(ok=False, action=plan.action, error_code='ROW_OUT_OF_RANGE',
                                         message='The requested row is not present in the search results.')
                row = rows[index - 1] or {}
            required = ent.get('required_voice_presence')
            if required is not None and (required not in ('present','absent') or row.get('voice_presence') != required):
                return CommandResult(ok=False, action=plan.action, error_code='VOICE_EVIDENCE_CHANGED',
                    message='Voice availability changed or is unknown. Refresh the workflow evidence before opening this patient.')
            if not row.get('patient_id') or not row.get('study_uid'):
                return CommandResult(ok=False, action=plan.action, error_code='MISSING_STUDY_IDENTITY',
                                     message='That result has no complete study identity and cannot be opened safely.')
            ent = dict(row)
        patient_id = str(ent.get("patient_id") or ent.get("id") or "")
        if not patient_id:
            return CommandResult(
                ok=False, action="open_patient",
                message="open_patient requires entities.patient_id",
                error_code="MISSING_PATIENT_ID",
            )
        # Delegate to the existing adapter. Some installs expose
        # open_patient_by_id; fall back to open_patient.
        method = (
            getattr(self._home, "open_patient_by_id", None)
            or getattr(self._home, "open_patient", None)
        )
        if not callable(method):
            return CommandResult(
                ok=False, action="open_patient",
                message="HomeWidgetAdapter exposes no open_patient method",
                error_code="ADAPTER_INCOMPLETE",
            )
        try:
            # Signature-aware delegation (fix 2026-06-04, found via the test
            # control server): the LIVE HomeWidgetAdapter.open_patient takes
            # (patient_id, patient_name, study_uid, report_status="pending");
            # the old 2-branch dispatch called it as (patient_id, entities)
            # ط·آ·ط¢آ·ط·آ¢ط¢آ·ط·آ·ط¢آ¢ط·آ¢ط¢آ£ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ¢ط·آ·ط¢آ·ط·آ¢ط¢آ£ط·آ·ط¢آ¢ط·آ¢ط¢آ¢ط·آ·ط¢آ£ط·آ¢ط¢آ¢ط·آ£ط¢آ¢ط£آ¢أ¢â‚¬ع‘ط¢آ¬ط·آ¹أ¢â‚¬ع©ط·آ·ط¢آ¢ط·آ¢ط¢آ¬ط·آ·ط¢آ·ط·آ¢ط¢آ¢ط·آ·ط¢آ¢ط·آ¢ط¢آ ط·آ·ط¢آ·ط·آ¢ط¢آ£ط·آ·ط¢آ¢ط·آ¢ط¢آ¢ط·آ·ط¢آ£ط·آ¢ط¢آ¢ط·آ£ط¢آ¢ط£آ¢أ¢â‚¬ع‘ط¢آ¬ط·آ¹أ¢â‚¬ع©ط·آ·ط¢آ¢ط·آ¢ط¢آ¬ط·آ·ط¢آ£ط·آ¢ط¢آ¢ط·آ£ط¢آ¢ط£آ¢أ¢â‚¬ع‘ط¢آ¬ط£آ¢أ¢â€ڑآ¬ط¹â€ ط·آ·ط¢آ¢ط·آ¢ط¢آ¢ TypeError 'missing study_uid' on every live invocation. Fakes
            # with 1-arg / (id, entities) signatures keep their old branches.
            argc = getattr(getattr(method, "__code__", None), "co_argcount", 2)
            if argc >= 5:
                payload = method(
                    patient_id,
                    str(ent.get("patient_name") or ""),
                    str(ent.get("study_uid") or ""),
                    str(ent.get("report_status") or "pending"),
                )
            elif argc <= 2:
                payload = method(patient_id)
            else:
                payload = method(patient_id, ent)
        except Exception as exc:
            return CommandResult(
                ok=False, action="open_patient",
                message=f"open_patient failed: {exc}",
                error_code="HOME_OPEN_FAILED",
            )
        return CommandResult(
            ok=True, action="open_patient",
            message=f"Opened patient {patient_id}",
            data={"patient_id": patient_id, "study_uid": str(ent.get("study_uid") or ""), "payload": payload},
        )

